# ENGR 243 (Dynamics, Dr. Gomaa, Fall 2026) — theory/concept bank aligned to Lectures 1–22 (Beer & Johnston Ch 11–17).
C = "engr243"
L = lambda n, t: f"Lecture {n} – {t}"
Q = []
def mcq(id, topic, q, choices, ans, exp, src): Q.append(dict(id=f"e243-{id}", course=C, topic=topic, type="mcq", question=q, choices=choices, answer=ans, explanation=exp, source=src))
def tf(id, topic, q, ans, exp, src): Q.append(dict(id=f"e243-{id}", course=C, topic=topic, type="tf", question=q, answer=ans, explanation=exp, source=src))
def sa(id, topic, q, ans, exp, src, kw=()): Q.append(dict(id=f"e243-{id}", course=C, topic=topic, type="short", question=q, answer=ans, explanation=exp, source=src, keywords=list(kw)))

T = "Particle kinematics (Ch 11)"
mcq("pk-01", T, "If acceleration is given as a function of position, $a(x)$, the relation that links $v$ and $x$ is:", ["$v\\,dv=a\\,dx$", "$dv=a\\,dt$", "$dx=v\\,dt$", "$a=dv/dx$"], 0, "This comes from $a=\\frac{dv}{dt}=\\frac{dv}{dx}\\frac{dx}{dt}=v\\frac{dv}{dx}$.", L(1, "Rectilinear Motion"))
mcq("pk-02", T, "For uniformly accelerated rectilinear motion, which is correct?", ["$v^2=v_0^2+2a(x-x_0)$", "$v=v_0+ax$", "$x=x_0+v_0t+at^2$", "$v^2=v_0^2+at$"], 0, "Also $v=v_0+at$ and $x=x_0+v_0t+\\tfrac12at^2$. These hold only for constant $a$.", L(2, "Uniformly Accelerated Motion"))
tf("pk-03", T, "The area under a $v$–$t$ curve between $t_1$ and $t_2$ equals the change in position $x_2-x_1$.", True, "The area under an $a$–$t$ curve equals the change in velocity. The slope of $v$–$t$ is $a$.", L(1, "Rectilinear Motion"))
tf("pk-04", T, "Total distance travelled equals the displacement only if the particle never reverses direction.", True, "Find where $v=0$ and add the distances of each leg separately.", L(1, "Rectilinear Motion"))
mcq("pk-05", T, "Relative motion: $\\vec v_B=$", ["$\\vec v_A+\\vec v_{B/A}$", "$\\vec v_A-\\vec v_{B/A}$", "$\\vec v_{B/A}-\\vec v_A$", "$\\vec v_A\\vec v_{B/A}$"], 0, "This holds for a translating (non-rotating) reference frame.", L(3, "Relative & Dependent Motion"))
sa("pk-06", T, "How do you set up a dependent-motion (pulley/cable) problem?", "Write the total cable length as a sum of position coordinates measured from fixed points, $x_A+2x_B+\\dots=$ const. Differentiate once for velocities ($v_A+2v_B=0$) and twice for accelerations.", "There is one constraint equation per cable. Constant segments (around pulleys) drop out when you differentiate.", L(3, "Dependent Motion (Cables)"), ["cable length constant", "position from fixed datum", "differentiate"])
mcq("pk-07", T, "In projectile motion (no air resistance), which statement is TRUE?", ["The horizontal velocity stays constant and the vertical acceleration is $-g$", "Both velocity components are constant", "The horizontal acceleration is $g$", "The speed is constant"], 0, "Treat $x$ and $y$ independently and link them through time $t$.", L(5, "Projectile Motion"))
mcq("pk-08", T, "In normal–tangential coordinates, the acceleration components are:", ["$a_t=\\dot v$, $a_n=v^2/\\rho$", "$a_t=v^2/\\rho$, $a_n=\\dot v$", "$a_t=\\rho\\dot\\theta$, $a_n=0$", "$a_t=0$, $a_n=\\dot v$"], 0, "$a_n$ always points toward the centre of curvature.", L(5, "n-t Coordinates"))
tf("pk-09", T, "A car moving at constant speed around a curve has zero acceleration.", False, "$a_t=0$, but $a_n=v^2/\\rho\\ne0$ because the direction of the velocity changes.", L(6, "n-t Components"))
mcq("pk-10", T, "In polar ($r$–$\\theta$) coordinates, the radial acceleration is:", ["$a_r=\\ddot r-r\\dot\\theta^2$", "$a_r=\\ddot r$", "$a_r=r\\ddot\\theta+2\\dot r\\dot\\theta$", "$a_r=\\ddot r+r\\dot\\theta^2$"], 0, "$a_\\theta=r\\ddot\\theta+2\\dot r\\dot\\theta$, where $2\\dot r\\dot\\theta$ is the Coriolis-type term.", L(6, "r-θ Components"))
mcq("pk-11", T, "In polar coordinates, the velocity components are:", ["$v_r=\\dot r$, $v_\\theta=r\\dot\\theta$", "$v_r=r\\dot\\theta$, $v_\\theta=\\dot r$", "$v_r=\\dot r$, $v_\\theta=\\dot\\theta$", "$v_r=r$, $v_\\theta=\\theta$"], 0, "The radial part comes from the changing length of $r$. The transverse part comes from rotation of the position vector.", L(6, "r-θ Components"))

T = "Rigid-body kinematics (Ch 15)"
sa("rk-01", T, "Name the types of plane rigid-body motion.", "Translation (rectilinear or curvilinear), rotation about a fixed axis, and general plane motion (translation + rotation).", "In translation every point has the same $\\vec v$ and $\\vec a$, and $\\omega=0$.", L(7, "Translation & Fixed-Axis Rotation"), ["translation", "fixed-axis rotation", "general plane motion"])
tf("rk-02", T, "In curvilinear translation, all points of the body move along identical (parallel) curved paths and the body does not rotate.", True, "Example: a Ferris-wheel gondola that stays upright.", L(7, "Translation"))
mcq("rk-03", T, "For a point at distance $r$ from a fixed rotation axis:", ["$v=r\\omega$, $a_t=r\\alpha$, $a_n=r\\omega^2$", "$v=r\\alpha$, $a_t=r\\omega$, $a_n=r\\omega$", "$v=\\omega/r$, $a_t=\\alpha/r$", "$v=r\\omega^2$, $a_n=r\\omega$"], 0, "Vector form: $\\vec v=\\vec\\omega\\times\\vec r$ and $\\vec a=\\vec\\alpha\\times\\vec r-\\omega^2\\vec r$.", L(7, "Fixed-Axis Rotation"))
mcq("rk-04", T, "Two gears in mesh (radii $r_A$, $r_B$) satisfy:", ["$r_A\\omega_A=r_B\\omega_B$ (equal contact-point speed)", "$\\omega_A=\\omega_B$", "$r_B\\omega_A=r_A\\omega_B$", "$\\omega_A+\\omega_B=0$ with equal magnitudes"], 0, "Same for a belt with no slip: the belt speed equals $r\\omega$ on each pulley.", L(8, "Fixed-Axis Rotation Examples"))
mcq("rk-05", T, "For general plane motion, the relative velocity equation is:", ["$\\vec v_B=\\vec v_A+\\vec\\omega\\times\\vec r_{B/A}$", "$\\vec v_B=\\vec v_A+\\vec\\alpha\\times\\vec r_{B/A}$", "$\\vec v_B=\\vec v_A-\\omega^2\\vec r_{B/A}$", "$\\vec v_B=\\vec\\omega\\times\\vec v_A$"], 0, "The motion of B relative to A is a pure rotation about A.", L(8, "General Plane Motion"))
mcq("rk-06", T, "The instantaneous centre of zero velocity (IC) is located:", ["At the intersection of the lines perpendicular to the velocities of two points", "At the centre of mass always", "Where the acceleration is zero", "At the midpoint between two points"], 0, "Then $v_P=\\omega\\,r_{P/IC}$ for any point P, perpendicular to $\\vec r_{P/IC}$.", L(9, "IC Method"))
tf("rk-07", T, "The instantaneous centre has zero velocity AND zero acceleration at that instant.", False, "Its acceleration is generally not zero. That's why the IC can't be used for accelerations.", L(9, "IC Method"))
mcq("rk-08", T, "For a wheel of radius $r$ rolling without slipping, the centre O satisfies:", ["$v_O=r\\omega$, $a_O=r\\alpha$", "$v_O=0$", "$v_O=2r\\omega$", "$a_O=r\\omega^2$"], 0, "The contact point is the IC (velocity zero). Its acceleration is $r\\omega^2$, pointing up toward O.", L(9, "General Plane Motion"))
mcq("rk-09", T, "The top point of a wheel rolling without slipping at centre speed $v$ moves at:", ["$2v$", "$v$", "0", "$\\sqrt2\\,v$"], 0, "It is $2r$ from the IC at the contact point.", L(9, "IC Method"))
mcq("rk-10", T, "Relative acceleration in plane motion: $\\vec a_B=\\vec a_A+$", ["$\\vec\\alpha\\times\\vec r_{B/A}-\\omega^2\\vec r_{B/A}$", "$\\vec\\omega\\times\\vec r_{B/A}$", "$2\\vec\\omega\\times\\vec v_{rel}$", "$\\omega^2\\vec r_{B/A}$"], 0, "Tangential part $\\alpha r$ ⊥ $r_{B/A}$. Normal part $\\omega^2r$ points from B toward A.", L(9, "Acceleration"))
mcq("rk-11", T, "When a point moves relative to a rotating frame, the Coriolis acceleration is:", ["$2\\vec\\Omega\\times\\vec v_{rel}$", "$\\vec\\Omega\\times\\vec r$", "$\\Omega^2r$", "$\\vec\\alpha\\times\\vec r$"], 0, "$\\vec a_P=\\vec a_{P'}+\\vec a_{rel}+2\\vec\\Omega\\times\\vec v_{rel}$, where $P'$ is the coincident point of the rotating frame.", L(10, "Rotating Frames & Coriolis"))
tf("rk-12", T, "The Coriolis acceleration is zero if the collar has no velocity relative to the rotating rod, or if the rod is not rotating.", True, "It needs both $\\Omega\\ne0$ and $v_{rel}\\ne0$ (and not parallel).", L(11, "Coriolis Acceleration"))
sa("rk-13", T, "When should you use the absolute-motion (analytical) method for a mechanism?", "When the geometry gives a convenient position relation, e.g. $x=f(\\theta)$. Write the coordinate in terms of the angle and differentiate with respect to time (chain rule) to get $v$ and $a$ directly.", "This is an alternative to the relative-velocity and relative-acceleration vector equations.", L(10, "Absolute Motion"), ["position as function of angle", "differentiate in time", "chain rule"])

T = "Kinetics: Newton's 2nd law (Ch 12, 16)"
mcq("nk-01", T, "Newton's second law for a particle in n–t coordinates gives, in the normal direction:", ["$\\sum F_n=mv^2/\\rho$", "$\\sum F_n=m\\dot v$", "$\\sum F_n=0$", "$\\sum F_n=mv$"], 0, "The tangential direction gives $\\sum F_t=m\\dot v$.", L("11b & 13", "Newton's Second Law"))
tf("nk-02", T, "Centrifugal force is a real force that should appear on a free-body diagram in an inertial frame.", False, "In an inertial frame only real forces go on the FBD. $mv^2/\\rho$ belongs on the kinetic diagram ($m\\vec a$ side).", L("11b & 13", "Newton's Second Law"))
mcq("nk-03", T, "For a rigid body in plane motion, the equations of motion are:", ["$\\sum\\vec F=m\\vec a_G$ and $\\sum M_G=\\bar I\\alpha$", "$\\sum\\vec F=0$ and $\\sum M=0$", "$\\sum\\vec F=m\\vec a$ at any point and $\\sum M_O=0$", "$\\sum M_G=m a_G$"], 0, "Moments can also be taken about another point P: $\\sum M_P=\\bar I\\alpha+$ moment of $m\\vec a_G$ about P.", L(14, "Rigid Bodies – Forces & Acceleration"))
tf("nk-04", T, "For a rigid body in pure translation, $\\alpha=0$, so $\\sum M_G=0$, but moments about other points need not be zero.", True, "About a point P: $\\sum M_P=$ moment of $m\\vec a_G$ about P.", L(14, "Translation"))
mcq("nk-05", T, "For rotation about a fixed axis through O (not through G), a convenient moment equation is:", ["$\\sum M_O=I_O\\alpha$, with $I_O=\\bar I+md^2$", "$\\sum M_O=\\bar I\\alpha$", "$\\sum M_O=0$", "$\\sum M_O=m a_G d$ only"], 0, "Using O eliminates the unknown pin reactions from the moment equation.", L(15, "Fixed-Axis Rotation Kinetics"))
mcq("nk-06", T, "The parallel-axis theorem is:", ["$I=\\bar I+md^2$", "$I=\\bar I-md^2$", "$I=md^2$", "$I=\\bar I\\,d^2$"], 0, "$\\bar I$ is about the parallel centroidal axis, and $d$ is the distance between the axes.", L(15, "Fixed-Axis Rotation Kinetics"))
sa("nk-07", T, "For a wheel rolling on a surface with friction, how do you decide between 'rolls without slipping' and 'slips'?", "Assume no slip ($a_G=r\\alpha$), solve for the friction force $F$, then check $F\\le\\mu_sN$. If the check fails, it slips: use $F=\\mu_kN$ and treat $a_G$ and $\\alpha$ as independent.", "This is the standard assume-and-check procedure.", L(16, "Rolling with Friction"), ["assume no slip", "a = rα", "check F ≤ μs N", "else F = μk N"])
mcq("nk-08", T, "A disk pulled horizontally at its centre rolls without slipping. Static friction at the contact point:", ["Acts opposite to the pull and provides the moment that spins the disk up", "Is always zero", "Acts in the direction of the pull", "Equals $\\mu_kN$"], 0, "If friction were zero, the disk would slide without rotating.", L(16, "Rolling with Friction"))
tf("nk-09", T, "The mass moment of inertia of a thin ring about its central axis ($mr^2$) is larger than that of a solid disk of the same mass and radius ($\\tfrac12mr^2$).", True, "The ring's mass sits farther from the axis, so it accelerates more slowly when rolling down an incline.", L(15, "Rotation Kinetics"))

T = "Work & energy (Ch 13, 17)"
mcq("we-01", T, "The principle of work and energy is:", ["$T_1+\\sum U_{1\\to2}=T_2$", "$T_1=T_2$ always", "$\\sum F=ma$", "$m v_1+\\int F dt=mv_2$"], 0, "$T=\\tfrac12mv^2$ for a particle. Work is a scalar, so no vector components are needed.", L(17, "Energy Method (Particles)"))
mcq("we-02", T, "The work done by a linear spring as it stretches from $x_1$ to $x_2$ is:", ["$-\\tfrac12k(x_2^2-x_1^2)$", "$\\tfrac12k(x_2-x_1)^2$", "$-k(x_2-x_1)$", "$kx_2x_1$"], 0, "$x$ is measured from the unstretched length. The potential energy is $V_e=\\tfrac12kx^2$.", L(17, "Energy Method (Particles)"))
tf("we-03", T, "The normal force on a particle sliding along a fixed surface does no work.", True, "It is perpendicular to the displacement. Kinetic friction does negative work.", L(17, "Energy Method (Particles)"))
mcq("we-04", T, "Conservation of energy $T_1+V_1=T_2+V_2$ applies when:", ["Only conservative forces (gravity, springs) do work", "Friction is present", "Any forces act", "The body is at rest"], 0, "Otherwise use $T_1+V_1+U^{nc}_{1\\to2}=T_2+V_2$.", L(17, "Energy Method (Particles)"))
mcq("we-05", T, "The kinetic energy of a rigid body in plane motion is:", ["$\\tfrac12m\\bar v^2+\\tfrac12\\bar I\\omega^2$", "$\\tfrac12m\\bar v^2$ only", "$\\tfrac12I\\omega$", "$m\\bar v+\\bar I\\omega$"], 0, "For fixed-axis rotation about O: $T=\\tfrac12I_O\\omega^2$. You can also use $\\tfrac12I_{IC}\\omega^2$.", L(18, "Energy Method (Rigid Bodies)"))
tf("we-06", T, "For a wheel rolling without slipping, the friction force at the contact point does no work.", True, "The contact point has zero velocity, so friction there does no work and energy is conserved if no other non-conservative forces act.", L(18, "Energy Method (Rigid Bodies)"))
mcq("we-07", T, "Power is:", ["$P=\\vec F\\cdot\\vec v$ (or $M\\omega$ for a couple)", "$P=Fd$", "$P=\\tfrac12mv^2$", "$P=F/v$"], 0, "Efficiency = output power ÷ input power.", L(17, "Energy Method"))
tf("we-08", T, "The work of a couple $M$ rotating through $\\Delta\\theta$ is $U=M\\Delta\\theta$ (for constant $M$).", True, "Positive when $M$ and the rotation are in the same direction.", L(18, "Energy Method (Rigid Bodies)"))
mcq("we-09", T, "The gravitational potential energy of a body near Earth's surface is:", ["$V_g=Wy$, with $y$ measured upward from a datum", "$V_g=-Wy$", "$V_g=\\tfrac12Wy^2$", "$V_g=mg/y$"], 0, "The datum is arbitrary because only changes matter.", L(17, "Energy Method"))

T = "Impulse & momentum (Ch 13, 17)"
mcq("im-01", T, "The principle of linear impulse and momentum for a particle is:", ["$m\\vec v_1+\\sum\\int_{t_1}^{t_2}\\vec F\\,dt=m\\vec v_2$", "$T_1+U=T_2$", "$\\vec F=m\\vec a$", "$m v_1^2+Ft=mv_2^2$"], 0, "It's a vector equation, so use components. Best when forces act over a known time.", L(19, "Impulse & Momentum (Particles)"))
mcq("im-02", T, "Linear momentum of a system is conserved when:", ["The net external impulse on the system is zero", "Energy is conserved", "The bodies stick together", "Friction is absent between the bodies"], 0, "Internal forces cancel in pairs. Momentum can be conserved in one direction even if not in another.", L(19, "Impulse & Momentum"))
mcq("im-03", T, "The coefficient of restitution $e$ for a direct central impact is:", ["$e=\\dfrac{v_B'-v_A'}{v_A-v_B}$ (separation speed ÷ approach speed)", "$e=\\dfrac{v_A-v_B}{v_B'-v_A'}$", "$e=v_A'/v_A$", "$e=T_2/T_1$"], 0, "$e=1$ perfectly elastic. $e=0$ perfectly plastic (bodies stick).", L(22, "Conservation & Restitution"))
tf("im-04", T, "In a perfectly elastic impact ($e=1$), kinetic energy is conserved.", True, "For $e<1$, some kinetic energy is lost to deformation, heat and sound.", L(22, "Restitution"))
tf("im-05", T, "In an oblique central impact of two smooth spheres, momentum of each sphere is conserved separately along the tangent to the contact plane.", True, "Along the line of impact, use total momentum conservation plus the restitution equation.", L(22, "Restitution"))
mcq("im-06", T, "The angular momentum of a rigid body in plane motion about its mass centre is:", ["$H_G=\\bar I\\omega$", "$H_G=m\\bar v$", "$H_G=\\tfrac12\\bar I\\omega^2$", "$H_G=\\bar I\\alpha$"], 0, "About a fixed axis O: $H_O=I_O\\omega$.", L(21, "Angular Momentum Method"))
mcq("im-07", T, "Angular momentum about a point O is conserved when:", ["The net angular impulse of external forces about O is zero", "Linear momentum is conserved", "There is no friction anywhere", "The body is in translation"], 0, "Example: a body pinned at O struck by a projectile. The large unknown pin impulse has no moment about O.", L(22, "Conservation"))
sa("im-08", T, "When should you choose impulse–momentum over work–energy?", "When the problem involves time (forces acting over a given time interval), impulsive forces such as impacts, or when velocities before and after are related but distances aren't known. Work–energy suits problems relating speed to position or distance.", "Impact problems need momentum, because energy is not conserved in impacts unless $e=1$.", L(19, "Impulse & Momentum"), ["time", "impacts", "energy for distance"])
tf("im-09", T, "During a short impact, non-impulsive forces such as body weight and spring forces can usually be neglected.", True, "Their impulse $F\\Delta t$ is negligible because $\\Delta t\\to0$, unlike the large impact force.", L(19, "Impulse & Momentum"))
mcq("im-10", T, "A figure skater pulls her arms in while spinning. Her angular velocity:", ["Increases, because $I\\omega$ is conserved and $I$ decreases", "Decreases", "Stays the same", "Drops to zero"], 0, "Her kinetic energy actually increases, from the work her muscles do.", L(22, "Conservation"))
